create table if not exists public.ls_arena63(id bigint generated always as identity primary key,a uuid not null,b uuid not null,mode text not null,deck jsonb not null,topic text,pa text,pb text,la int default 1,lb int default 1,ha int default 100,hb int default 100,round int default 0,turn uuid,status text default 'pending',winner uuid,last_actor uuid,last_action text,seq int default 0);
alter table public.ls_arena63 enable row level security;
revoke all on public.ls_arena63 from anon,authenticated;
create or replace function public.ls_arena_create63(peer uuid,kind text,subject text,cards jsonb,pet text,lvl int) returns bigint language plpgsql security definer set search_path='' as $$ declare n bigint; begin if auth.uid() is null or not exists(select 1 from public.ls_connections c where c.accepted and ((c.sender=auth.uid() and c.recipient=peer) or(c.recipient=auth.uid() and c.sender=peer))) then raise exception 'Keine Freundschaft'; end if; if kind not in ('classic','learn','ranked') or jsonb_typeof(cards)<>'array' or jsonb_array_length(cards)>200 or pg_column_size(cards)>500000 or (kind<>'classic' and jsonb_array_length(cards)<4) then raise exception 'Ungültiges Battle'; end if; insert into public.ls_arena63(a,b,mode,deck,topic,pa,la,turn) values(auth.uid(),peer,kind,cards,left(subject,100),pet,greatest(1,least(5,lvl)),auth.uid()) returning id into n; return n; end $$;
create or replace function public.ls_arena_list63() returns setof jsonb language sql security definer set search_path='' as $$ select (to_jsonb(t)-'deck') || jsonb_build_object('question',case when t.status='active' then t.deck->(t.round % greatest(1,jsonb_array_length(t.deck)))->'q' end) from public.ls_arena63 t where auth.uid() in(t.a,t.b) order by id desc $$;
create or replace function public.ls_arena_join63(bid bigint,pet text,lvl int,accept boolean) returns void language plpgsql security definer set search_path='' as $$ begin update public.ls_arena63 set pb=pet,lb=greatest(1,least(5,lvl)),status=case when accept then 'active' else 'declined' end where id=bid and b=auth.uid() and status='pending'; end $$;
create or replace function public.ls_arena_act63(bid bigint,expected int,action text,answer text) returns void language plpgsql security definer set search_path='' as $$ declare t public.ls_arena63%rowtype; me uuid:=auth.uid(); dmg int; begin select * into t from public.ls_arena63 where id=bid and me in(a,b) for update; if not found or t.status<>'active' or t.seq<>expected then return; end if; if action='quit' then t.winner:=case when me=t.a then t.b else t.a end; elsif t.mode='classic' then if t.turn<>me then return; end if; if action='heal' then if me=t.a then t.ha:=least(100,t.ha+12); else t.hb:=least(100,t.hb+12); end if; elsif action in ('attack','special') then dmg:=case when action='special' and t.seq%3=0 then 28 else 18 end; if me=t.a then t.hb:=greatest(0,t.hb-dmg); else t.ha:=greatest(0,t.ha-dmg); end if; else return; end if; t.turn:=case when me=t.a then t.b else t.a end; else if action<>'answer' or lower(trim(answer)) is distinct from lower(trim(t.deck->(t.round % jsonb_array_length(t.deck))->>'a')) then raise exception 'Antwort nicht richtig'; end if; if me=t.a then t.hb:=greatest(0,t.hb-20); else t.ha:=greatest(0,t.ha-20); end if; t.round:=t.round+1; end if; if t.ha=0 then t.winner:=t.b; elsif t.hb=0 then t.winner:=t.a; end if; update public.ls_arena63 set ha=t.ha,hb=t.hb,round=t.round,turn=t.turn,winner=t.winner,status=case when t.winner is null then 'active' else 'finished' end,last_actor=me,last_action=action,seq=t.seq+1 where id=bid; end $$;
revoke execute on function public.ls_arena_create63(uuid,text,text,jsonb,text,int),public.ls_arena_list63(),public.ls_arena_join63(bigint,text,int,boolean),public.ls_arena_act63(bigint,int,text,text) from public,anon;
grant execute on function public.ls_arena_create63(uuid,text,text,jsonb,text,int),public.ls_arena_list63(),public.ls_arena_join63(bigint,text,int,boolean),public.ls_arena_act63(bigint,int,text,text) to authenticated;
